svg.script:
(function(){
 const root=document.documentElement;
 function apply(el,on){el.dataset.painted=on?'1':'0';el.style.fill=on?el.dataset.suggested:'#fffdf8';}
 function trigger(el,all){const next=el.dataset.painted!=='1';if(all)root.querySelectorAll('.region[data-color="'+el.dataset.color+'"]').forEach(x=>apply(x,next));else apply(el,next);}
 root.querySelectorAll('.region').forEach(el=>{el.dataset.painted='1';el.addEventListener('click',e=>trigger(el,e.shiftKey));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();trigger(el,e.shiftKey)}})});
 root.querySelectorAll('.swatch').forEach(sw=>{const run=()=>root.querySelectorAll('.region[data-color="'+sw.dataset.paletteNumber+'"]').forEach(x=>apply(x,true));sw.addEventListener('click',run);sw.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();run()}})});
})();
